public class PolymorphismDemo {

    // Compile-time polymorphism: Method Overloading
    public double calculateArea(double radius) {
        return Math.PI * radius * radius;
    }

    public double calculateArea(double length, double width) {
        return length * width;
    }

    public static abstract class Processor {
        // Runtime polymorphism: Method Overriding target
        public abstract void process();
    }

    public static class VideoProcessor extends Processor {
        @Override
        public void process() {
            System.out.println("Processing video stream...");
        }
    }

    public static class AudioProcessor extends Processor {
        @Override
        public void process() {
            System.out.println("Processing audio stream...");
        }
    }

    public static void executeJob(Processor processor) {
        // Runtime polymorphism in action (Dynamic Dispatch)
        processor.process();
    }

    public static void main(String[] args) {
        PolymorphismDemo demo = new PolymorphismDemo();
        // Compile-time resolution
        System.out.println(demo.calculateArea(5.0));
        System.out.println(demo.calculateArea(4.0, 3.0));

        // Runtime resolution
        executeJob(new VideoProcessor());
        executeJob(new AudioProcessor());
    }
}
